class Solution {
public:
    int minimumLevel(TreeNode* root) {
        queue<TreeNode*> q;
        q.push(root);
        long long best = LLONG_MAX;
        int answer = 1, level = 0;
        while (!q.empty()) {
            int sz = q.size();
            long long sum = 0;
            ++level;
            while (sz--) {
                TreeNode* u = q.front(); q.pop();
                sum += u->val;
                if (u->left) q.push(u->left);
                if (u->right) q.push(u->right);
            }
            if (sum < best) { best = sum; answer = level; }
        }
        return answer;
    }
};
